import { handleEdge } from "./edge/router";
import type { EdgeEnv } from "./edge/types";

const worker = {
  async fetch(request: Request, env: EdgeEnv, ctx: unknown): Promise<Response> {
    const response = await handleEdge(request, env);
    if (response) return response;
    // Keep Next/Auth.js/Prisma off the lightweight API request path entirely.
    // @ts-expect-error Generated by OpenNext during the production build.
    const { default: next } = await import("./.open-next/worker.js");
    return next.fetch(request, env, ctx);
  },
};

export default worker;
